import{_ as a,a as t,b as i,c as r,d as o}from"./chunks/CAL20.BDesHKIj.js";import{_ as n,o as s,c as l,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{"source_hash":"54556a9422","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/calibrate/troubleshoot.md","filePath":"fr/calibrate/troubleshoot.md"}'),c={name:"fr/calibrate/troubleshoot.md"};function u(p,e,m,b,h,g){return s(),l("div",null,[...e[0]||(e[0]=[d('<h3 id="native-algorithm" tabindex="-1">Algorithme natif <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Algorithme natif {#native-algorithm}&quot;">​</a></h3><p>Si vous utilisez xDrip avec l&#39;algorithme natif d&#39;un G6, G7, ONE, ONE+ ou Stelo, voir <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">ici</a>.</p><h3 id="xdrip-algorithm" tabindex="-1">Algorithme de xDrip <a class="header-anchor" href="#xdrip-algorithm" aria-label="Permalink to &quot;Algorithme de xDrip {#xdrip-algorithm}&quot;">​</a></h3><p>Activez les <a href="./../use/lesscommon.html#show-data-tables">tables de données</a> pour plus d&#39;informations.</p><h4 id="no-data-after-initial-calibration" tabindex="-1">Pas de données après l&#39;étalonnage initial <a class="header-anchor" href="#no-data-after-initial-calibration" aria-label="Permalink to &quot;Pas de données après l&#39;étalonnage initial {#no-data-after-initial-calibration}&quot;">​</a></h4><img src="'+a+'" style="zoom:75%;"><p>Si vous avez vérifié la connexion avec le capteur/transmetteur et qu&#39;aucune donnée n&#39;apparaît après l&#39;étalonnage initial, c&#39;est peut-être parce que vous étalonnez trop haut et que l&#39;ordonnée à l&#39;origine calculée dépasse la limite de sécurité. <a href="./calibrate.html#reset-all-calibrations">Réinitialisez</a> toutes les calibrations et réessayez à glycémie stable, dans la plage basse.</p><h4 id="no-data-after-adding-a-new-calibration" tabindex="-1">Pas de données après l&#39;ajout d&#39;une nouvelle calibration <a class="header-anchor" href="#no-data-after-adding-a-new-calibration" aria-label="Permalink to &quot;Pas de données après l&#39;ajout d&#39;une nouvelle calibration {#no-data-after-adding-a-new-calibration}&quot;">​</a></h4><img src="'+t+'" style="zoom:75%;"><p>Vous avez probablement fait sortir les calibrations des limites de sécurité. Consultez le Tableau de calibrations et, si nécessaire, <a href="./calibrate.html#disable-a-calibration">désactivez</a> la calibration en cause.</p><p>Un capteur qui nécessite une forte ordonnée à l&#39;origine positive n&#39;est peut-être pas sûr. Si vous pensez que votre capteur est encore fiable, <a href="./calibrate.html#reset-all-calibrations">réinitialisez</a> toutes les calibrations et réessayez à glycémie stable, dans la plage basse.</p><h4 id="new-calibration-is-ignored" tabindex="-1">La nouvelle calibration est ignorée <a class="header-anchor" href="#new-calibration-is-ignored" aria-label="Permalink to &quot;La nouvelle calibration est ignorée {#new-calibration-is-ignored}&quot;">​</a></h4><img src="'+i+'" style="zoom:75%;"><p>Consultez le Tableau de calibrations : vous y verrez très probablement vos calibrations affichées en rouge, car elles sont désactivées pour des raisons de sécurité.</p><p>Votre capteur n&#39;est très probablement plus fiable. Si vous pensez qu&#39;il l&#39;est, <a href="./calibrate.html#reset-all-calibrations">réinitialisez</a> toutes les calibrations et réessayez à glycémie stable, dans la plage basse.</p><h4 id="intercept-or-slope-above-safety-limit" tabindex="-1">Ordonnée à l&#39;origine ou pente au-delà de la limite de sécurité <a class="header-anchor" href="#intercept-or-slope-above-safety-limit" aria-label="Permalink to &quot;Ordonnée à l&#39;origine ou pente au-delà de la limite de sécurité {#intercept-or-slope-above-safety-limit}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Sécurité</p><p>Les limites qui vous empêchent d&#39;étalonner sont conçues pour votre propre sécurité.<br><strong>Vous ne pouvez pas vous fier à un système incapable de détecter une hypoglycémie.</strong></p></div><p>Ouvrez votre Tableau de calibrations et vérifiez la dernière calibration.</p><img src="'+r+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">L&#39;ordonnée à l&#39;origine maximale autorisée est de 39</p><p>Une ordonnée à l&#39;origine supérieure à 39 mg/dl empêche l&#39;affichage de la glycémie pour des raisons de sécurité.</p></div><p>Les limites de pente dépendent de votre capteur :</p><table tabindex="0"><thead><tr><th>Capteur</th><th>Pente minimale</th><th>Pente maximale</th></tr></thead><tbody><tr><td>G5 ou G6 algorithme non natif (3 calibrations ou plus)</td><td>0,7</td><td>1,6</td></tr><tr><td>G5 ou G6 algorithme non natif (exactement 2 calibrations)</td><td>0,75</td><td>1,5</td></tr><tr><td>Libre (source de données brutes, Pentes du Libre non fixées activé)</td><td>0,5</td><td>1,6</td></tr><tr><td>Libre (source de données brutes, pente fixe par défaut)</td><td>1 (fixe)</td><td>1 (fixe)</td></tr><tr><td>Libre 2 application patchée</td><td>1 (fixe)</td><td>1 (fixe)</td></tr></tbody></table><p>Comme les limites de sécurité de la pente et de l&#39;ordonnée à l&#39;origine empêchent xDrip d&#39;avoir une ordonnée à l&#39;origine trop élevée, les calibrations qui mèneraient à cette situation sont ignorées.</p><p>Dans l&#39;exemple ci-dessous, la ligne orange est celle qui correspond le mieux aux calibrations ; pourtant, xDrip utilise la rouge par sécurité, car son ordonnée à l&#39;origine est sûre. La valeur d&#39;ordonnée à l&#39;origine du plugin montre ce qui correspondrait mieux aux calibrations.</p><img src="'+o+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 7/12/2024</em></a></p>',27)])])}const x=n(c,[["render",u]]);export{_ as __pageData,x as default};
